import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_conv2d_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Tile configuration
constexpr int TILE_H   = 16;
constexpr int TILE_W   = 32;
constexpr int OC_TILE  = 32;
constexpr int OW_PER_THREAD = 2;
constexpr int THREADS_X = TILE_W / OW_PER_THREAD;

__global__ void conv2d_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ Bias,
    float* __restrict__ Y,
    int N, int C, int H, int Win,
    int OC, int IC_per_group, int OC_per_group, int K,
    int stride, int padding, int dilation,
    int Hout, int Wout,
    int TILE_H_in, int TILE_W_in,
    int num_oc_tiles)
{
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * THREADS_X + tx;
    const int nthreads = TILE_H * THREADS_X;
    const int ow0 = blockIdx.x * TILE_W;
    const int oh0 = blockIdx.y * TILE_H;
    const int bz = blockIdx.z;
    const int n = bz / num_oc_tiles;
    const int oc_tile_idx = bz % num_oc_tiles;
    const int oc_base = oc_tile_idx * OC_TILE;
    const int group = oc_base / OC_per_group;
    const int ic_start = group * IC_per_group;
    const int ic_end = ic_start + IC_per_group;
    // Global tensors via CuTe
    int64_t sXn = (int64_t)C * H * Win;
    int64_t sXc = (int64_t)H * Win;
    int64_t sXh = (int64_t)Win;
    int64_t sYn = (int64_t)OC * Hout * Wout;
    int64_t sYc = (int64_t)Hout * Wout;
    int64_t sYh = (int64_t)Wout;
    auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                           make_shape(C, H, Win),
                           make_stride(sXc, sXh, Int<1>{}));
    auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                           make_shape(OC, Hout, Wout),
                           make_stride(sYc, sYh, Int<1>{}));
    auto mW = make_tensor(make_gmem_ptr(Wt),
                           make_shape(OC, IC_per_group, K, K),
                           make_stride((int64_t)IC_per_group * K * K,
                                       (int64_t)K * K, K, Int<1>{}));
    // Double-buffered shared memory: input tile + weight chunk (2 copies)
    // to allow prefetching the next input-channel's data while the
    // current input-channel's data is being consumed by the compute loop.
    extern __shared__ float smem[];
    const int in_tile_sz = TILE_H_in * TILE_W_in;
    const int w_tile_sz  = OC_TILE * K * K;
    float* sIn_ptr[2];
    float* sW_ptr[2];
    sIn_ptr[0] = smem;
    sIn_ptr[1] = smem + in_tile_sz;
    sW_ptr[0]  = smem + 2 * in_tile_sz;
    sW_ptr[1]  = sW_ptr[0] + w_tile_sz;
    auto make_sIn_view = [&](float* p) {
        return make_tensor(make_smem_ptr(p),
                            make_shape(TILE_H_in, TILE_W_in),
                            make_stride(TILE_W_in, Int<1>{}));
    };
    auto make_sW_view = [&](float* p) {
        return make_tensor(make_smem_ptr(p),
                            make_shape(Int<OC_TILE>{}, K, K),
                            make_stride(K * K, K, Int<1>{}));
    };
    const int oh = oh0 + ty;
    int ow[OW_PER_THREAD];
    bool ow_valid[OW_PER_THREAD];
    #pragma unroll
    for (int i = 0; i < OW_PER_THREAD; ++i) {
        ow[i] = ow0 + tx * OW_PER_THREAD + i;
        ow_valid[i] = (ow[i] < Wout);
    }
    const bool oh_valid = (oh < Hout);
    float acc[OC_TILE][OW_PER_THREAD];
    #pragma unroll
    for (int oo = 0; oo < OC_TILE; ++oo) {
        int oc = oc_base + oo;
        float bval = 0.0f;
        if (Bias != nullptr && oc < OC) bval = Bias[oc];
        #pragma unroll
        for (int i = 0; i < OW_PER_THREAD; ++i) {
            acc[oo][i] = bval;
        }
    }
    const int total_in = in_tile_sz;
    const int total_w  = w_tile_sz;
    auto load_tile = [&](int ic, float* inp, float* wp) {
        int ic_local = ic - ic_start;
        for (int idx = tid; idx < total_in; idx += nthreads) {
            int r = idx / TILE_W_in;
            int c = idx - r * TILE_W_in;
            int ih = oh0 * stride - padding + r;
            int iw = ow0 * stride - padding + c;
            float v = 0.0f;
            if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
                v = mX(ic, ih, iw);
            }
            inp[idx] = v;
        }
        for (int idx = tid; idx < total_w; idx += nthreads) {
            int oo = idx / (K * K);
            int rem = idx - oo * (K * K);
            int kh = rem / K;
            int kw = rem - kh * K;
            int oc = oc_base + oo;
            float v = 0.0f;
            if (oc < OC) {
                v = mW(oc, ic_local, kh, kw);
            }
            wp[idx] = v;
        }
    };
    // Prologue: prefetch first input-channel tile into buffer 0
    load_tile(ic_start, sIn_ptr[0], sW_ptr[0]);
    __syncthreads();
    int cur = 0;
    for (int ic = ic_start; ic < ic_end; ++ic) {
        auto sIn_cur = make_sIn_view(sIn_ptr[cur]);
        auto sW_cur  = make_sW_view(sW_ptr[cur]);
        int next_ic = ic + 1;
        int nxt = cur ^ 1;
        if (next_ic < ic_end) {
            // Issue the loads for the next input channel's tile now so
            // their global-memory latency overlaps with the compute
            // below that consumes the already-resident current tile.
            load_tile(next_ic, sIn_ptr[nxt], sW_ptr[nxt]);
        }
        if (oh_valid) {
            for (int kh = 0; kh < K; ++kh) {
                int r = ty * stride + kh * dilation;
                for (int kw = 0; kw < K; ++kw) {
                    float xval[OW_PER_THREAD];
                    #pragma unroll
                    for (int i = 0; i < OW_PER_THREAD; ++i) {
                        int c = (tx * OW_PER_THREAD + i) * stride + kw * dilation;
                        xval[i] = sIn_cur(r, c);
                    }
                    #pragma unroll
                    for (int oo = 0; oo < OC_TILE; ++oo) {
                        float wval = sW_cur(oo, kh, kw);
                        #pragma unroll
                        for (int i = 0; i < OW_PER_THREAD; ++i) {
                            acc[oo][i] += xval[i] * wval;
                        }
                    }
                }
            }
        }
        __syncthreads();
        cur = nxt;
    }
    if (oh_valid) {
        #pragma unroll
        for (int oo = 0; oo < OC_TILE; ++oo) {
            int oc = oc_base + oo;
            if (oc < OC) {
                #pragma unroll
                for (int i = 0; i < OW_PER_THREAD; ++i) {
                    if (ow_valid[i]) {
                        mY(oc, oh, ow[i]) = acc[oo][i];
                    }
                }
            }
        }
    }
}

torch::Tensor cute_conv2d_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding, int dilation, int groups) {
    TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    TORCH_CHECK(x.dim() == 4, "x must be [N,C,H,W]");
    TORCH_CHECK(w.dim() == 4, "w must be [OC, IC/groups, K, K]");

    if (b.has_value()) {
        TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA");
        TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
    }

    auto x_c = x.contiguous();
    auto w_c = w.contiguous();

    int64_t N   = x_c.size(0);
    int64_t C   = x_c.size(1);
    int64_t H   = x_c.size(2);
    int64_t Win = x_c.size(3);

    int64_t OC = w_c.size(0);
    int64_t IC_per_group = w_c.size(1);
    int64_t K  = w_c.size(2);
    TORCH_CHECK(w_c.size(3) == K, "kernel must be square");
    TORCH_CHECK(groups > 0 && (C % groups) == 0 && (OC % groups) == 0,
                "invalid groups configuration");
    TORCH_CHECK(IC_per_group == C / groups, "weight IC dim mismatch with groups");

    int64_t OC_per_group = OC / groups;

    TORCH_CHECK(stride > 0 && dilation > 0 && padding >= 0, "invalid conv params");

    int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    int64_t Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");

    torch::Tensor b_c;
    const float* b_ptr = nullptr;
    if (b.has_value()) {
        b_c = b.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
        b_ptr = b_c.data_ptr<float>();
    }

    auto y = torch::empty({N, OC, Hout, Wout}, x.options());

    int TILE_H_in = (TILE_H - 1) * stride + (int)(K - 1) * dilation + 1;
    int TILE_W_in = (TILE_W - 1) * stride + (int)(K - 1) * dilation + 1;

    int num_oc_tiles = (int)((OC + OC_TILE - 1) / OC_TILE);

    dim3 block(THREADS_X, TILE_H);
    dim3 grid(
        (unsigned)((Wout + TILE_W - 1) / TILE_W),
        (unsigned)((Hout + TILE_H - 1) / TILE_H),
        (unsigned)(N * num_oc_tiles)
    );

    size_t smem_bytes = (size_t)2 * (TILE_H_in * TILE_W_in + OC_TILE * K * K) * sizeof(float);

    if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(conv2d_kernel,
                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                              (int)smem_bytes);
    }

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv2d_kernel<<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)C, (int)H, (int)Win,
        (int)OC, (int)IC_per_group, (int)OC_per_group, (int)K,
        stride, padding, dilation,
        (int)Hout, (int)Wout,
        TILE_H_in, TILE_W_in,
        num_oc_tiles
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 2D convolution implemented with a custom cooperative-tiled CUDA kernel
    built using CuTe tensors/layouts for indexing.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.in_channels // self.groups) * self.kernel_size * self.kernel_size
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

