    }
    if (oh_valid) {
        #pragma unroll
        for (int oo = 0; oo < OC_TILE; ++oo) {
            int oc = oc_base + oo;
            if (oc < OC) {
                #pragma unroll
                for (int i = 0; i < OW_PER_THREAD; ++i) {
                    if (ow_valid[i]) {
                        mY(oc, oh, ow[i]) = acc[oo][i];
                    }
                }
            }
        }
    }
}

torch::Tensor cute_conv2d_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding, int dilation, int groups) {
    TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    TORCH_CHECK(x.dim() == 4, "x must be [N,C,H,W]");
    TORCH_CHECK(w.dim() == 4, "w must be [OC, IC/groups, K, K]");

    if (b.has_value()) {
        TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA");
        TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
    }

    auto x_c = x.contiguous();
    auto w_c = w.contiguous();

    int64_t N   = x_c.size(0);
    int64_t C   = x_c.size(1);
    int64_t H   = x_c.size(2);
    int64_t Win = x_c.size(3);

    int64_t OC = w_c.size(0);
    int64_t IC_per_group = w_c.size(1);
    int64_t K  = w_c.size(2);
    TORCH_CHECK(w_c.size(3) == K, "kernel must be square");
    TORCH_CHECK(groups > 0 && (C % groups) == 0 && (OC % groups) == 0,
                "invalid groups configuration");
    TORCH_CHECK(IC_per_group == C / groups, "weight IC dim mismatch with groups");

    int64_t OC_per_group = OC / groups;

    TORCH_CHECK(stride > 0 && dilation > 0 && padding >= 0, "invalid conv params");

    int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    int64_t Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");

    torch::Tensor b_c;
    const float* b_ptr = nullptr;
    if (b.has_value()) {
        b_c = b.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
        b_ptr = b_c.data_ptr<float>();
    }

    auto y = torch::empty({N, OC, Hout, Wout}, x.options());

    int TILE_H_in = (TILE_H - 1) * stride + (int)(K - 1) * dilation + 1;
    int TILE_W_in = (TILE_W - 1) * stride + (int)(K - 1) * dilation + 1;

    int num_oc_tiles = (int)((OC + OC_TILE - 1) / OC_TILE);

    dim3 block(THREADS_X, TILE_H);
    dim3 grid(
        (unsigned)((Wout + TILE_W - 1) / TILE_W),
        (unsigned)((Hout + TILE_H - 1) / TILE_H),
        (unsigned)(N * num_oc_tiles)
    );

    size_t smem_bytes = (size_t)2 * (TILE_H_in * TILE_W_in + OC_TILE * K * K) * sizeof(float);

    if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(conv2d_kernel,
                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                              (int)smem_bytes);
    }

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv2d_kernel<<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)C, (int)H, (int)Win,
        (int)OC, (int)IC_per_group, (int)OC_per_group, (int)K,
        stride, padding, dilation,
        (int)Hout, (int)Wout,
        TILE_H_in, TILE_W_in,
        num_oc_tiles
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
